CREATE VIEW `view_combine_alive_riyousha` (`email`,`riyousha_id`,`riyousha_code`,`role_base`,`role_has`,`all_name`,`search_text`) AS with `t1` as (select `user_role`.`user_role_id` AS `user_role_id`,`user_role`.`email` AS `email`,`user_role`.`is_latest` AS `is_latest`,`user_role`.`role` AS `role`,`user_role`.`kanrensha_code` AS `kanrensha_code`,`user_role`.`riyousha_code` AS `riyousha_code`,`user_role`.`insert_user_id` AS `insert_user_id`,`user_role`.`insert_user_code` AS `insert_user_code`,`user_role`.`insert_user_name` AS `insert_user_name`,`user_role`.`insert_timestamp` AS `insert_timestamp`,`user_role`.`delete_user_id` AS `delete_user_id`,`user_role`.`delete_user_code` AS `delete_user_code`,`user_role`.`delete_user_name` AS `delete_user_name`,`user_role`.`delete_timestamp` AS `delete_timestamp` from `user_role` where ((`user_role`.`is_latest` = 1) and (`user_role`.`role` in ('manager','partner_api','admin')) and (`user_role`.`riyousha_code` <> 0))), `riyousha_alive` as (select `view_riyousha_alive`.`email` AS `email`,`view_riyousha_alive`.`user_role` AS `user_role`,`view_riyousha_alive`.`riyousha_id` AS `riyousha_id`,`view_riyousha_alive`.`riyousha_code` AS `riyousha_code`,`view_riyousha_alive`.`all_name` AS `all_name`,`view_riyousha_alive`.`search_text` AS `search_text` from `view_riyousha_alive` where (`view_riyousha_alive`.`riyousha_code` <> 0)) select `t1`.`email` AS `email`,`riyousha_alive`.`riyousha_id` AS `riyousha_id`,`t1`.`riyousha_code` AS `riyousha_code`,`t1`.`role` AS `role_base`,`t2`.`role` AS `role2_has`,`riyousha_alive`.`all_name` AS `all_name`,`riyousha_alive`.`search_text` AS `search_text` from ((`user_role` `t2` left join `t1` on((`t2`.`email` = `t1`.`email`))) left join `riyousha_alive` on(((`riyousha_alive`.`user_role` = `t1`.`role`) and (`riyousha_alive`.`riyousha_code` = `t1`.`riyousha_code`) and (`riyousha_alive`.`email` = `t1`.`email`)))) where ((`t2`.`is_latest` = 1) and (`t2`.`role` in ('manager','partner_api','admin')) and (`t1`.`email` is not null));
